[Form]
public class METVendPackingSlipJournal extends FormRun implements SysIFilterConsumerForm, SysIFilterEventHandler, METItemInquiryFilerProvider
{
    FormRun formRun;

}

public void init()
{
    formRun = element.args().caller() as FormRun;
    super();    
}

/// <summary>
/// Register the data source to which the filter should be applied.
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    METRecentlyReceivedPOView_ds.OnQueryExecuting += eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
}

 //Returns the current ItemId filter value
public ItemId parmItemIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(ItemId));

}

public InventLocationId parminventoryLocationIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(InventLocationId));
}

/// <summary>
/// Event handler to react on a filter change.
/// </summary>
public void onFilterChanged()
{
    METRecentlyReceivedPOView_ds.research();
    METRecentlyReceivedPOView_ds.executeQuery();
}

/// <summary>
///
/// </summary>
public void executeQuery()
{
    ItemId                  itemIdFilter;
    InventLocationId        inventLocationIdFilter;
    utcdatetime             curDateTime, past7DateTime;
    QueryBuildDataSource    qbdsRecentlyReceivedPOView;

    if (formRun)
    {
        itemIdFilter            = formRun.parmItemId();
        inventLocationIdFilter  = formRun.parminventoryLocationId();

        curDateTime     = DateTimeUtil::utcNow();
        past7DateTime   = DateTimeUtil::addDays(curDateTime, -7);

        qbdsRecentlyReceivedPOView = this.queryBuildDataSource();
        qbdsRecentlyReceivedPOView.clearRanges();

        qbdsRecentlyReceivedPOView.addRange(fieldNum(METRecentlyReceivedPOView, DeliveryDate)).value(strFmt("%1..%2", past7DateTime, curDateTime));


        if (itemIdFilter)
        {
            qbdsRecentlyReceivedPOView.addRange(fieldNum(METRecentlyReceivedPOView, ItemId)).value(itemIdFilter);
            qbdsRecentlyReceivedPOView.addRange(fieldNum(METRecentlyReceivedPOView, ItemId)).status(RangeStatus::Locked);
        }

        if (inventLocationIdFilter)
        {
            qbdsRecentlyReceivedPOView.addRange(fieldNum(METRecentlyReceivedPOView, InventLocationId)).value(inventLocationIdFilter);
            qbdsRecentlyReceivedPOView.addRange(fieldNum(METRecentlyReceivedPOView, InventLocationId)).status(RangeStatus::Locked);
        }
    }
    super();
}
